using NUnit.Framework;
using Smartest.Rounds;

namespace Smartest.Tests
{
    /// <summary>
    /// Originally generated by an oracle.py from an earlier session (it isn't in the project).
    /// The Pick a Pill, Snap, Door, Pot, Silent Auction and Sus cases were later updated for their
    /// fixed rules, and Undercut, Gold Rush and Mirror Match added, again from an independent
    /// Python model of the rule text.
    ///
    /// Every expected value here was computed by an independent Python model of the rule,
    /// not read out of the C#. If the two disagree, one of them is wrong and the test says
    /// so, instead of quietly agreeing with a bug.
    /// </summary>
    public class ResolverTests
    {
        private static RoundContext Ctx(int[] answers, int[] scores, int subRound)
        {
            int n = answers.Length;
            var s = scores ?? new int[n];
            var names = new string[n];
            for (int i = 0; i < n; i++) names[i] = "P" + (i + 1);
            return new RoundContext { PlayerCount = n, Answers = answers, Scores = s, Names = names, SubRound = subRound };
        }

        private static void Check(int id, int[] answers, int[] scores, int subRound,
            int[] expected, string key, bool expectContinue = false)
        {
            var def = RoundCatalog.CreateDefinition(RoundCatalog.Get(id));
            var r = ResolverRegistry.Resolve(def, Ctx(answers, scores, subRound));
            Assert.AreEqual(expected, r.Deltas, "round " + id + " deltas");
            Assert.AreEqual(key, r.OutcomeKey, "round " + id + " outcome key");
            Assert.AreEqual(expectContinue, r.ContinueSubRounds, "round " + id + " sub-round continuation");
            UnityEngine.Object.DestroyImmediate(def);
        }

        // ---- 1 TheButton ----
