        [Test] public void C01_TheButton_OneRedBetrays() => Check(1, new[] { 1, 0, 0 }, null, 1, new[] { 15, -5, -5 }, "someRed");
        [Test] public void C01_TheButton_TwoRedsGreensPay() => Check(1, new[] { 1, 1, 0, 0 }, null, 1, new[] { 15, 15, -5, -5 }, "someRed");
        [Test] public void C01_TheButton_AllRedCollapses() => Check(1, new[] { 1, 1, 1 }, null, 1, new[] { -10, -10, -10 }, "allRed");
        [Test] public void C01_TheButton_NoAnswerCountsGreen() => Check(1, new[] { 1, -1, 0 }, null, 1, new[] { 15, -5, -5 }, "someRed");
