        [Test] public void C02_PickAPill_TwoPlayersLoneRedWins() => Check(2, new[] { 1, 0 }, null, 1, new[] { 8, 3 }, "redWins");
        [Test] public void C02_PickAPill_NobodyTookRed() => Check(2, new[] { 0, 0, 0 }, null, 1, new[] { 3, 3, 3 }, "noRed");
