        [Test] public void C03_TheSnap_TooManyReds() => Check(3, new[] { 1, 1, 1, 0 }, null, 1, new[] { -5, -5, -5, -5 }, "unbalanced");
        [Test] public void C03_TheSnap_NoReds() => Check(3, new[] { 0, 0, 0, 0 }, null, 1, new[] { -5, -5, -5, -5 }, "unbalanced");
        [Test] public void C03_TheSnap_TwoPlayersOneVanishes() => Check(3, new[] { 1, 0 }, null, 1, new[] { 0, 10 }, "balanced");
