        [Test] public void C04_TheDoor_NobodyClimbed() => Check(4, new[] { 1, 1, 1 }, null, 1, new[] { 0, 0, 0 }, "none");
        [Test] public void C04_TheDoor_SilenceIsNotClimbing() => Check(4, new[] { 1, 1, -1 }, null, 1, new[] { 0, 0, 0 }, "none");
        [Test] public void C04_TheDoor_SilenceDoesNotSinkTheClimber() => Check(4, new[] { 0, -1, 1 }, null, 1, new[] { 15, 0, 0 }, "one");
