        [Test] public void C10_SilentAuction_ZeroSitsOut() => Check(10, new[] { 0, 3, 3 }, null, 1, new[] { 0, 7, 7 }, "reveal");

        [Test]
        public void C10_SilentAuction_ZeroIsAValidBid()
        {
            // The "nobody bid" reveal line only makes sense if not bidding is an answer you can give.
            var def = RoundCatalog.CreateDefinition(RoundCatalog.Get(10));
            Assert.IsTrue(def.IsValidAnswer(0));
            UnityEngine.Object.DestroyImmediate(def);
        }
